package com.openjiuwen.studio.agent.manager.utils;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import com.openjiuwen.studio.agent.common.exception.AgentStudioException;
import com.openjiuwen.studio.agent.manager.obs.MgObsService;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.mockito.Answers;
import org.mockito.MockedStatic;
import org.mockito.Mockito;
import org.mockito.MockitoAnnotations;
import org.mockito.junit.jupiter.MockitoSettings;
import org.mockito.quality.Strictness;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;

import javax.imageio.ImageIO;

/**
 * 功能描述
 *
 */
@MockitoSettings(strictness = Strictness.LENIENT)
class ImageBase64UtilsTest extends BaseTest {
    private AutoCloseable mockitoCloseable;

    private static MockedStatic<ImageBase64Utils> mockedImageStatic;


    @BeforeEach
    void setUp() throws Exception {
        mockitoCloseable = MockitoAnnotations.openMocks(this);
    }

    @AfterEach
    void tearDown() throws Exception {
        mockitoCloseable.close();
    }

    @Test
    void test_getImageBase64_should_equal_result_when_condition() throws Exception {
        // Given
        MgObsService mgObsService = mock(MgObsService.class, Answers.RETURNS_DEEP_STUBS);
        String mockBase64Content =
            "}\n";
        when(mgObsService.downloadObsImageFile(anyString())).thenReturn(mockBase64Content);

        // When
        String result = ImageBase64Utils.getImageBase64("default.png", mgObsService);

        // Then
        String expected = "data:image/png;base64," + mockBase64Content;
        assertEquals(expected, result);
    }

    @Test
    void test_getImageBase64_should_throws_agent_manager_exception_when_mgObsService_is_null() throws Exception {
        // Given
        String iconName = "default.png";
        // When & Then
        assertThrows(AgentStudioException.class, () -> {
            ImageBase64Utils.getImageBase64(iconName, null);
        });
    }

    @Test
    void test_getImageBase64_should_throw_agent_manager_exception_when_iconName_is_null() {
        // Given
        MgObsService mgObsService = mock(MgObsService.class);

        // When & Then
        assertThrows(AgentStudioException.class, () -> {
            ImageBase64Utils.getImageBase64(null, mgObsService);
        });
    }

    @Test
    void test_getImageBase64_should_throw_null_pointer_exception_when_both_parameters_are_null() throws Exception {
        // When & Then
        assertThrows(AgentStudioException.class, () -> {
            String result = ImageBase64Utils.getImageBase64(null, null);
        });
    }

    @Test
    void test_validateImage_should_throw() {
        String image4 = "";
        assertThrows(AgentStudioException.class, () -> {
            ImageBase64Utils.validateImage(image4);
        });
        String image5 = "";
        ImageBase64Utils.validateImage(image5);

        String image = "data:image/git;base64,";
        assertThrows(AgentStudioException.class, () -> {
            ImageBase64Utils.validateImage(image);
        });
        String image2 = "data:image/png;base64,";
        assertThrows(AgentStudioException.class, () -> {
            ImageBase64Utils.validateImage(image2, 1);
        });

        String image3 = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAtA@@@@@@@";
        try (MockedStatic<ImageBase64Utils> mockedImageStatic = Mockito.mockStatic(ImageBase64Utils.class)) {
            mockedImageStatic.when(() -> ImageBase64Utils.isValidBase64Image(anyString())).thenReturn(true);
            mockedImageStatic.when(() -> ImageBase64Utils.validateImage(anyString(), any(Integer.class))).thenCallRealMethod();
            assertThrows(AgentStudioException.class, () -> {
                ImageBase64Utils.validateImage(image3, 10);
            });
        }
    }

    @Test
    public void test_resizeBase64Image_valid_input_returns_resized_image() throws Exception {
        try (MockedStatic<ImageIO> imageIOMock = Mockito.mockStatic(ImageIO.class)) {
            BufferedImage originalImage = mock(BufferedImage.class);
            BufferedImage resizedImage = mock(BufferedImage.class);
            Graphics2D graphics2D = mock(Graphics2D.class);

            imageIOMock.when(() -> ImageIO.read(any(ByteArrayInputStream.class))).thenReturn(originalImage);
            imageIOMock.when(() -> ImageIO.write(any(BufferedImage.class), anyString(), any(ByteArrayOutputStream.class)))
                .thenReturn(true);

            when(resizedImage.createGraphics()).thenReturn(graphics2D);

            String base64Image = "data:image/png;base64,validBase64Data";
            String result = ImageBase64Utils.resizeBase64Image(base64Image, 128, 128);

            assertNotNull(result);
            assertTrue(result.startsWith("data:image/png;base64,"));
        }
    }

    @Test
    public void test_resizeBase64Image_invalid_base64_throws_exception() throws Exception {
        String base64Image = "invalidBase64";
        assertThrows(IllegalArgumentException.class, () -> {
            ImageBase64Utils.resizeBase64Image(base64Image, 128, 128);
        });
    }

}
